import java.util.*;import java.time.*;import world.creve.playpit.util.PetalLayout;import world.creve.playpit.service.PostingPolicy;import world.creve.playpit.validation.MessagePolicy;import world.creve.playpit.entity.MessageStatus;import world.creve.platform.exception.*;import world.creve.platform.util.SafeUrls;
public class LocalPolicyProbe{static int passed=0;static void ok(boolean c,String n){if(!c)throw new AssertionError(n);passed++;}static void rejects(Runnable r,String n){try{r.run();throw new AssertionError("accepted "+n);}catch(IllegalArgumentException|InvalidMessageException|RateLimitExceededException e){passed++;}}
 public static void main(String[]args){long[]counts={0,1,10,11,30,31,60,61,300,301};int[]stages={0,1,1,2,2,3,3,4,4,4};for(int i=0;i<counts.length;i++)ok(PetalLayout.growth(counts[i])==stages[i],"growth");rejects(()->PetalLayout.growth(-1),"negative");for(int i=0;i<3;i++){PostingPolicy.check(i,false);passed++;}rejects(()->PostingPolicy.check(3,false),"fourth");rejects(()->PostingPolicy.check(0,true),"duplicate");ok(PostingPolicy.WINDOW.getSeconds()==60,"seconds");ok(PostingPolicy.DUPLICATE_WINDOW.toMinutes()==10,"minutes");for(int n:new int[]{1,299,300})ok(MessagePolicy.evaluate("あ".repeat(n),null)==MessageStatus.PUBLISHED,"length");for(String v:new String[]{""," ","　","\t\n","あ".repeat(301),"<script>x</script>","https://example.invalid"})rejects(()->MessagePolicy.evaluate(v,null),"invalid content");rejects(()->MessagePolicy.evaluate(null,null),"null");rejects(()->MessagePolicy.evaluate("x","名".repeat(31)),"name");ok(MessagePolicy.evaluate("x","名".repeat(30))==MessageStatus.PUBLISHED,"name30");ok(MessagePolicy.evaluate("a@example.invalid",null)==MessageStatus.PENDING,"PII");ok(MessagePolicy.evaluate("090-1234-5678",null)==MessageStatus.PENDING,"phone");Set<String>points=new HashSet<>();for(long i=1;i<=5000;i++){long seed=PetalLayout.seed(i,Math.max(1,PetalLayout.growth(i)));var p=PetalLayout.position(seed);ok(p.equals(PetalLayout.position(seed)),"stable");ok(p.x()>0&&p.x()<100&&p.y()>0&&p.y()<100,"bounds");ok(points.add(Double.toHexString(p.x())+":"+Double.toHexString(p.y())),"distinct");ok(PetalLayout.type(seed)>=1&&PetalLayout.type(seed)<=5,"type");}for(String v:new String[]{"javascript:alert(1)","//evil.invalid","data:text/html,hi","https://u:p@example.invalid"})rejects(()->SafeUrls.optional(v),"URL");ok(SafeUrls.optional("https://example.invalid").startsWith("https"),"https");ok(SafeUrls.optional("/playpit/images/a.svg").startsWith("/playpit"),"path");System.out.println("ASSERTIONS_PASSED="+passed+"; actual production policy/layout sources; no stubs; no Spring runtime");}}
